768  // the only entry point - unpack a JSON object into gpsdata_t substructures
   769  int libgps_json_unpack(const char *buf,
   770                         struct gps_data_t *gpsdata, const char **end)
   771  {
   772      int status;
   773      char *classtag = strstr(buf, "\"class\":");
   774
   775      if (NULL == classtag) {
   776          return -1;
   777      }
   778
   779      if (str_starts_with(classtag, "\"class\":\"TPV\"")) {
   780          status = json_tpv_read(buf, gpsdata, end);
   781          gpsdata->set = STATUS_SET;
   782          if (0 != gpsdata->fix.time.tv_sec) {
   783              gpsdata->set |= TIME_SET;
   784          }
   785          if (0 != isfinite(gpsdata->fix.ept)) {
   640
   641      return status;
   642  }
