   644  int json_toff_read(const char *buf, struct gps_data_t *gpsdata,
   645                             const char **endptr)
   646  {
   647      int real_sec = 0, real_nsec = 0, clock_sec = 0, clock_nsec = 0;
   648      const struct json_attr_t json_attrs_toff[] = {
   649          // *INDENT-OFF*
   650          {"class",     t_check,   .dflt.check = "TOFF"},
   651          {"device",    t_string,  .addr.string = gpsdata->dev.path,
   652                                   .len = sizeof(gpsdata->dev.path)},
   653          {"real_sec",  t_integer, .addr.integer = &real_sec,
   654                                   .dflt.integer = 0},
   655          {"real_nsec", t_integer, .addr.integer = &real_nsec,
   656                                   .dflt.integer = 0},
   657          {"clock_sec", t_integer, .addr.integer = &clock_sec,
   658                                   .dflt.integer = 0},
   659          {"clock_nsec",t_integer, .addr.integer = &clock_nsec,
   660                                   .dflt.integer = 0},
   661          // ignore unknown keys, for cross-version compatibility
   662          {"", t_ignore},
   663          {NULL},
   664          // *INDENT-ON*
   665      };
   666      int status;
   667
   668      memset(&gpsdata->toff, 0, sizeof(gpsdata->toff));
   669      status = json_read_object(buf, json_attrs_toff, endptr);
   670      gpsdata->toff.real.tv_sec = (time_t)real_sec;
   671      gpsdata->toff.real.tv_nsec = (long)real_nsec;
   672      gpsdata->toff.clock.tv_sec = (time_t)clock_sec;
   673      gpsdata->toff.clock.tv_nsec = (long)clock_nsec;
   674      if (status != 0)
   675          return status;
   961  int json_read_object(const char *cp, const struct json_attr_t *attrs,
   962                       const char **end)
   963  {
   964      int st;
   965
   966      json_debug_trace((1, "json_read_object() sees '%s'\n", cp));
   967      st = json_internal_read_object(cp, attrs, NULL, 0, end);
   968      return st;
   969  }
